/*
 * display.h — SkySentinel v0.5.9
 * UI with selective redraw (no full-screen sprite — heap can't support
 * a 115KB buffer alongside BLE/WiFi/queues). Flicker is eliminated by
 * only repainting pixels that actually changed each frame: static labels
 * draw once per state change, dynamic bits redraw in-place without touching the background.
 * Dashboard final polish + dark product-style splash screen. Bitmap logo + clean UI font. Animation-heavy effects remain deferred.
 * Touch via tft.getTouch() — ggaljoen fork SoftSPI, no XPT2046 library
 * 320x240 landscape, ILI9341_2_DRIVER
 */
#pragma once
#include <TFT_eSPI.h>
#include "ble_scan.h"
#include "settings.h"

// ── GPS / state externs ───────────────────────────────────────────────────────
extern volatile float   gpsLat, gpsLon, gpsSpeedKnots, gpsCourse, gpsAltM;
extern volatile uint8_t gpsSats;
extern volatile bool    gpsTimeValid;
extern volatile uint8_t gpsHour, gpsMinute, gpsSecond;
extern bool    sdReady;
extern uint8_t brightness;
void applyBrightness();  // defined in SkySentinel.ino
extern volatile uint8_t gpsMonth;
extern volatile uint8_t gpsDay;

// ── North America timezone lookup ─────────────────────────────────────────────
// Approximate by longitude band — covers contiguous US/Canada/Mexico.
// Not exact at borders, but far more reliable than a generic 15deg formula.
// Falls back to Eastern if outside this range.
struct TZBand { float lonMax; int8_t offsetStd; };
static const TZBand NA_TZ_BANDS[] = {
  { -141.0f, -9 },   // far west AK edge (rare)
  { -125.0f, -8 },   // Pacific
  { -104.0f, -7 },   // Mountain
  {  -90.0f, -6 },   // Central
  {  -68.0f, -5 },   // Eastern
  {  -52.0f, -4 },   // Atlantic (e.g. Maritimes)
};
static const int NA_TZ_BAND_COUNT = 6;

// US DST: ~2nd Sunday in March to ~1st Sunday in November.
// Approximated with a day-of-month check — good enough for a dashboard
// clock; never used for logged timestamps, which stay UTC.
static bool isLikelyUSDST(uint8_t month, uint8_t day) {
  if (month < 3 || month > 11) return false;
  if (month > 3 && month < 11) return true;
  if (month == 3)  return day >= 8;
  if (month == 11) return day < 7;
  return false;
}

static int8_t getNATimezoneOffset(float lon, uint8_t month, uint8_t day) {
  int8_t offset = -5;  // default Eastern if out of band range
  for (int i = 0; i < NA_TZ_BAND_COUNT; i++) {
    if (lon <= NA_TZ_BANDS[i].lonMax) { offset = NA_TZ_BANDS[i].offsetStd; break; }
  }
  if (isLikelyUSDST(month, day)) offset += 1;
  return offset;
}

// ── Touch calibration (set in displayInit / orientation flip) ─────────────────
// Real measured touch calibration — captured separately for each rotation
// using CYD_Cal_ggaljoen. Do not guess/derive one from the other; the 5th
// value (orientation byte) is not a simple flip and must be measured.
static const uint16_t TOUCH_CAL_ROT1[5] = { 191, 3555, 323, 3496, 1 };  // unflipped
static const uint16_t TOUCH_CAL_ROT3[5] = { 193, 3559, 280, 3533, 7 };  // flipped

static void getTouchCalData(bool flipped, uint16_t* out) {
  memcpy(out, flipped ? TOUCH_CAL_ROT3 : TOUCH_CAL_ROT1, 10);
}

static uint16_t _calData[5];

// ── Colors ────────────────────────────────────────────────────────────────────
#define C_BG        0x0000
#define C_PANEL_BG  0x0000
#define C_HDR_BG    0x0000
#define C_DIV       0x1082
#define C_DRONE     0xF800
#define C_FLOCK     0x051F
#define C_WHITE     0xFFFF
#define C_GRAY      0x7BEF
#define C_DIM       0x39E7
#define C_GREEN     0x07E0
#define C_YELLOW    0xFFE0
#define C_SKY       0x051F
#define C_SCAN_ON   0x07E0
#define C_SCAN_OFF  0x1082

// ── Layout (320x240 landscape) ────────────────────────────────────────────────
#define SCR_W   320
#define SCR_H   240
#define HDR_H    22
#define SCAN_H   16
#define STAT_H   20
#define PANEL_Y  HDR_H
#define PANEL_H  (SCR_H - HDR_H - SCAN_H - STAT_H)   // 180
#define PANEL_W  ((SCR_W - 2) / 2)                     // 159
#define DIV_X    PANEL_W
#define RIGHT_X  (PANEL_W + 2)
#define SCAN_Y   (PANEL_Y + PANEL_H)
#define STAT_Y   (SCAN_Y + SCAN_H)
#define LP_CX    (PANEL_W / 2)
#define RP_CX    (RIGHT_X + PANEL_W / 2)

// ── Sprite canvas helpers ─────────────────────────────────────────────────────
// CV  = sprite when available, else tft
// PY  = y relative to panel top (sprite uses 0-based, tft uses PANEL_Y-based)
#define CV   _tft
#define PY(y) (int16_t)(PANEL_Y + (y))

// ── Log buffer ────────────────────────────────────────────────────────────────
#define LOG_MAX 30
enum LogType { LOG_FLOCK, LOG_DRONE };
struct LogEntry {
  LogType  type;
  char     mac[18], name[24];
  uint8_t  matchReason;
  int8_t   rssi;
  uint32_t timestamp;
};
static LogEntry _log[LOG_MAX];
static uint8_t  _logHead = 0, _logCount = 0;

// ── Detection state ───────────────────────────────────────────────────────────
static bool     _droneDetected = false, _flockDetected = false;
static int8_t   _droneRSSI = 0,   _flockRSSI = 0;
static char     _droneMethod[16] = "---", _flockMethod[16] = "---";
static uint32_t _droneLastMs = 0,  _flockLastMs = 0;
static char     _droneMAC[18] = "", _flockMAC[18] = "";

// ── UI state ──────────────────────────────────────────────────────────────────
static uint8_t  _activePage   = 0;
static uint8_t  _scanTick     = 0;
static uint32_t _lastScanMs   = 0;
static uint32_t _lastRedrawMs = 0;

// Selective redraw caches. No sprites and no full-region wipes per tick.
static bool _pageStaticDirty = true;
static char _lastClockStr[12] = "";
static int8_t _lastGpsFix = -1;
static int8_t _lastSdReady = -1;

struct PanelCache {
  int8_t mode = -1;       // 0 searching, 1 fresh detected, 2 stale last-seen
  int8_t rssi = 127;
  char method[16] = "";
  uint16_t lastSeenSec = 65535;
  bool borderOn = false;
};
static PanelCache _dronePanelCache;
static PanelCache _flockPanelCache;

// GPS page selective redraw cache. The GPS screen used to flicker because it
// wiped/redrew the full panel every 500ms. Keep the labels/static frame drawn
// once, then only overwrite changed value fields.
static bool _gpsStaticDrawn = false;
static char _gpsLatCache[18] = "";
static char _gpsLonCache[18] = "";
static char _gpsAltCache[18] = "";
static char _gpsSatCache[8]  = "";
static char _gpsSpdCache[18] = "";
static char _gpsHdgCache[18] = "";
static int8_t _gpsNoConnCache = -1;

static bool _headerStaticDrawn = false;
static bool _scanStaticDrawn = false;
static bool _statusStaticDrawn = false;

// ── Objects ───────────────────────────────────────────────────────────────────
static TFT_eSPI*    _tft        = nullptr;
// No full-panel sprite — 115KB doesn't fit in available heap alongside
// BLE/WiFi/queues (~95KB free at boot). Flicker is solved via selective
// redraw instead: only repaint regions that actually changed each frame.

// ── Forward declarations ──────────────────────────────────────────────────────
void drawHeader();
void drawMainPage();
void drawDronePanel();
void drawFlockPanel();
void drawPanel(bool isDrone, bool detected, int8_t rssi,
               const char* method, const char* mac, uint32_t lastMs);
void drawRSSIBars(int16_t px, int16_t py, int8_t rssi, uint16_t col);


